388: 					    "Dictation mode (depends on one of these speech synthesizers: %s)", 1));
389: 	ttip = g_strdup_printf (tmp, "Espeak");
390: 	g_free (tmp);
391: 	gtk_widget_set_tooltip_text (get_wg ("checkbutton_speech"), ttip);
392: 	callbacks_shield_set (FALSE);
