1153: G_MODULE_EXPORT void
1154: on_dialog_confirm_show (GtkWidget * widget, gpointer user_data)
1155: {
1156: 	gchar *action;
1157: 	gchar *msg;
1158: 	gchar *tmp;
1159: 	gint len;
