1400: 	callbacks_shield_set (TRUE);
1401: 	for (i = 0; i < 4; i++)
1402: 		gtk_combo_box_text_remove (GTK_COMBO_BOX_TEXT (get_wg ("combobox_stat_type")), 0);
1403: 	tmp = g_strdup_printf ("%s (%%)", _("Accuracy"));
